import {ToolRegistry} from './registry.js';

function exposeLegacyDataPath(registry: ToolRegistry, path: (instancePath: string) => string): void {
  const ajv = Reflect.get(registry, 'ajv') as {
    compile: (schema: object) => ((input: Record<string, unknown>) => boolean) & {errors?: unknown[]};
  };
  const originalCompile = ajv.compile.bind(ajv);
  ajv.compile = schema => {
    const validator = originalCompile(schema);
    const legacyValidator = ((input: Record<string, unknown>) => {
      const valid = validator(input);
      if (!valid && validator.errors) {
        const error = validator.errors[0] as {dataPath?: string; instancePath?: string};
        error.dataPath = path(error.instancePath ?? '');
        delete error.instancePath;
      }
      legacyValidator.errors = validator.errors;
      return valid;
    }) as ((input: Record<string, unknown>) => boolean) & {errors?: unknown[]};
    return legacyValidator;
  };
}

function registerWeatherTool(registry: ToolRegistry, executorCalls: {value: number}): void {
  registry.register(
    {
      name: 'get_weather',
      description: 'Get weather for a location',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
    },
    async () => {
      executorCalls.value += 1;
      return 'sunny';
    }
  );
}

describe('ToolRegistry input validation', () => {
  // spec: specs/hal-engine-tool-input-validation#1
  it('returns a rejection for missing required input without invoking the executor', async () => {
    const registry = new ToolRegistry();
    const executorCalls = {value: 0};
    registerWeatherTool(registry, executorCalls);

    const response = await registry.execute('get_weather', {});

    expect({
      resultNamesRequiredLocation: /location.*required/i.test(response.result),
      executorCalls: executorCalls.value,
    }).toEqual({resultNamesRequiredLocation: true, executorCalls: 0});
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('reports the expected type for a rejected property without exposing its value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup_record',
        description: 'Look up a record by identifier',
        inputSchema: {
          type: 'object',
          properties: {identifier: {type: 'string'}},
          required: ['identifier'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('lookup_record', {identifier: 123456789});

    expect({
      resultNamesFieldAndType: response.result.includes('identifier') && response.result.includes('string'),
      leaksValue: response.result.includes('123456789'),
      executorCalls,
    }).toEqual({resultNamesFieldAndType: true, leaksValue: false, executorCalls: 0});
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('reports a nested rejected property using its field path', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup_profile',
        description: 'Look up a profile',
        inputSchema: {
          type: 'object',
          properties: {
            profile: {
              type: 'object',
              properties: {name: {type: 'string'}},
            },
          },
          required: ['profile'],
        },
      },
      async () => 'found'
    );

    const response = await registry.execute('lookup_profile', {profile: {name: 123}});

    expect(response.result).toContain("property 'profile.name'");
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('reports a rejected property when the validator exposes a legacy data path', async () => {
    const registry = new ToolRegistry();
    exposeLegacyDataPath(registry, instancePath => instancePath.replace(/^\//, '.'));
    registry.register(
      () => ({
        name: 'legacy_path',
        description: 'Validate a legacy path',
        inputSchema: {type: 'object', properties: {identifier: {type: 'string'}}, required: ['identifier']},
      }),
      async () => 'found'
    );

    const response = await registry.execute('legacy_path', {identifier: 123});

    expect(response.result).toContain("property 'identifier'");
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('strips a legacy input root from a rejected property path', async () => {
    const registry = new ToolRegistry();
    exposeLegacyDataPath(registry, instancePath => `.input${instancePath}`);
    registry.register(
      () => ({
        name: 'legacy_root_path',
        description: 'Validate a legacy root path',
        inputSchema: {type: 'object', properties: {identifier: {type: 'string'}}, required: ['identifier']},
      }),
      async () => 'found'
    );

    const response = await registry.execute('legacy_root_path', {identifier: 123});

    expect(response.result).toContain("property 'identifier'");
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('normalizes a slash-separated legacy input root in a rejected path', async () => {
    const registry = new ToolRegistry();
    exposeLegacyDataPath(registry, instancePath => `.input${instancePath}`);
    registry.register(
      () => ({
        name: 'legacy_slash_path',
        description: 'Validate a slash-separated legacy path',
        inputSchema: {type: 'object', properties: {profile: {type: 'object', properties: {name: {type: 'string'}}}}},
      }),
      async () => 'found'
    );

    const response = await registry.execute('legacy_slash_path', {profile: {name: 123}});

    expect(response.result).toContain("property 'profile.name'");
  });

  // spec: specs/hal-engine-tool-input-validation#3
  it('names the tool when a static schema cannot be compiled', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_static_schema',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_static_schema/);
  });

  // spec: specs/hal-engine-tool-input-validation#6
  it('caches a function-valued schema validator by object reference', async () => {
    const registry = new ToolRegistry();
    const ajv = Reflect.get(registry, 'ajv') as {
      compile: (schema: object) => unknown;
    };
    const originalCompile = ajv.compile.bind(ajv);
    let compileCalls = 0;
    ajv.compile = schema => {
      compileCalls += 1;
      return originalCompile(schema);
    };
    const schema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    let executorCalls = 0;
    registry.register(
      () => ({
        name: 'cached_weather',
        description: 'Get weather for a location',
        inputSchema: schema,
      }),
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    await registry.execute('cached_weather', {location: 'Paris'});
    schema.required = ['city'];
    const response = await registry.execute('cached_weather', {location: 'Paris'});

    expect({compileCalls, result: response.result, executorCalls}).toEqual({
      compileCalls: 1,
      result: 'sunny',
      executorCalls: 2,
    });
  });
});

